import json

# Mapping learned from the examples
# Voiceless stops [k] are written g, [t] is t, [p] is p.
# Schwa: written ’ between two obstruents (an’stawteg, g’p’ta’q);
# omitted next to a sonorant l or n (tmi’gn, tplutaqan, mgumie’jo’tlatl).
# The word-final [tək] has the schwa between two obstruents, so it is written.

ipa = "alaptək"
cons_map = {"k": "g", "t": "t", "p": "p", "l": "l", "a": "a"}
sonorants = set("lnmw")
obstruents = set("ptkbdgcx")

out = []
for i, ch in enumerate(ipa):
    if ch == "ə":
        prev = ipa[i-1] if i > 0 else ""
        nxt = ipa[i+1] if i+1 < len(ipa) else ""
        if prev in obstruents and nxt in obstruents:
            out.append("’")
        # otherwise omitted
    else:
        out.append(cons_map.get(ch, ch))

answer = "".join(out)
print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "k->g": "[anəstawtek]=anstawteg, [gēgʷisink]=ge’gwising",
        "schwa between obstruents written ’": "an’stawteg(n-s), g’p’ta’q",
        "schwa near sonorant omitted": "tmi’gn, tplutaqan, lnu’sgw",
        "input": ipa
    }
}, ensure_ascii=False))
